#!/usr/bin/env node
/* biome-ignore-all lint/suspicious/noConsole: CLI entry point */
// This shim defers loading the real module until the compile cache is enabled.
// https://nodejs.org/api/module.html#moduleenablecompilecachecachedir
// enableCompileCache was added in Node.js 22.8.0, so we need to handle older versions.
try {
  const { enableCompileCache } = await import('node:module');
  if (enableCompileCache) {
    enableCompileCache();
  }
} catch {}

// Spawn the installed native binary for explicit opt-ins or internal automatic
// enrollment. Explicit opt-outs always override automatic enrollment.
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));

function resolveNative() {
  // Already running inside the native binary — never trampoline again.
  if (process.env.VERCEL_VC_NATIVE === '1') return null;
  const pkgName = `@vercel/vc-native-${process.platform}-${process.arch}`;
  const binName = process.platform === 'win32' ? 'vercel.exe' : 'vercel';
  // Walk up from this install's own tree looking for a sibling native
  // package. `require.resolve()` is not used because it falls back to
  // NODE_PATH and the global folders even when `paths` is given.
  let dir = __dirname;
  while (true) {
    const pkgDir = join(dir, 'node_modules', pkgName);
    if (existsSync(join(pkgDir, 'package.json'))) {
      const a = join(pkgDir, 'bin', binName);
      if (existsSync(a)) return a;
      const b = join(pkgDir, binName);
      if (existsSync(b)) return b;
    }
    const parent = dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}

// Read `--global-config`/`-Q` without loading the full CLI arg parser.
function globalConfigDirFromArgv() {
  const argv = process.argv.slice(2);
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--global-config' || arg === '-Q') {
      return argv[i + 1];
    }
    if (arg.startsWith('--global-config=')) {
      return arg.slice('--global-config='.length);
    }
  }
  return undefined;
}

// Any failure to read config counts as "not opted in".
async function isNativeBinaryOptedIn() {
  const envOverride = process.env.VERCEL_CLI_USE_NATIVE_BINARY;
  if (envOverride === '1' || envOverride === 'true') return true;
  if (envOverride === '0' || envOverride === 'false') return false;

  try {
    // Zod-free subpath to avoid loading zod + schemas on this hot path.
    const config = await import('@vercel/cli-config/paths');
    const argDir = globalConfigDirFromArgv();
    const configDir = argDir
      ? resolve(process.cwd(), argDir)
      : config.getGlobalPathConfig();
    const configPath = config.getConfigFilePath(configDir);
    const preference = config.readGlobalConfigFlag(
      configPath,
      'useNativeBinary'
    );
    if (typeof preference === 'boolean') return preference;
    return (
      config.readGlobalConfigFlag(configPath, 'nativeBinaryAutoOptIn') === true
    );
  } catch {
    return false;
  }
}

// Keep the opt-out escape hatch in Node even when the native binary cannot
// start. The full CLI parser still validates the command and its arguments.
const disableBinary = process.argv.slice(2).includes('--disable-binary');
const bin = disableBinary ? null : resolveNative();

// Internal worker arguments intentionally trampoline too. The packaged native
// binary sets VERCEL_VC_NATIVE=1 in pkg.js and re-enters this file, where
// resolveNative() returns null and the worker branch below handles the request.
if (bin && (await isNativeBinaryOptedIn())) {
  process.env.VERCEL_VC_NATIVE = '1';
  // Do not fall through to JS on spawn/loader failures — surface them so
  // native binary issues (e.g. glibc mismatch) are visible.
  const r = spawnSync(bin, process.argv.slice(2), {
    stdio: 'inherit',
    windowsHide: true,
  });
  if (r.error) {
    console.error(r.error.message);
    process.exit(1);
  }
  if (r.signal) {
    try {
      process.kill(process.pid, r.signal);
    } catch {}
  }
  process.exit(r.status ?? 1);
}

if (process.argv[2] === '--internal-build-worker') {
  const buildCommandReady = import('./commands/build/index.js');
  // The handoff observes this rejection after the transport module loads.
  // Attach immediately so a fast preload failure is not briefly unhandled.
  void buildCommandReady.catch(() => {});
  const { applyInternalBuildRequest, waitForInternalBuildRequest } =
    await import('./internal-build-worker.js');
  const handoff = await waitForInternalBuildRequest(
    process.argv.slice(2),
    buildCommandReady
  );
  globalThis[Symbol.for('vercel.cli.fatal-error-handler')] = error =>
    handoff.error(error);

  try {
    // The caller must provide the complete environment for a non-interactive
    // build-container invocation before normal CLI initialization starts.
    applyInternalBuildRequest(handoff.request);
    const { cliPromise } = await import('./index.js');
    const exitCode = await cliPromise;
    await handoff.complete(exitCode ?? 0);
  } catch (error) {
    await handoff.error(error);
    process.exitCode = 1;
  }

  process.exit(process.exitCode ?? 0);
}

// Fast path for --version to avoid loading the entire CLI
if (
  process.argv.length === 3 &&
  (process.argv[2] === '--version' || process.argv[2] === '-v')
) {
  const { version, buildLabel } = await import('./version.mjs');
  const labels = [];
  if (process.env.VERCEL_VC_NATIVE === '1') labels.push('native');
  // Optional build metadata stamped by CI (e.g. "pr-115 abc1234").
  if (buildLabel) labels.push(buildLabel);
  const suffix = labels.length > 0 ? ` (${labels.join(', ')})` : '';
  console.error(`Vercel CLI ${version}${suffix}`);
  console.log(version);
  process.exit(0);
}

// Fast path for --help to avoid loading the entire CLI
if (
  process.argv.length === 3 &&
  (process.argv[2] === '--help' || process.argv[2] === '-h')
) {
  const { version } = await import('./version.mjs');
  const { help } = await import('./help.js');
  console.error(`Vercel CLI ${version}`);
  console.error(help());
  process.exit(0);
}

await import('./index.js');
